const MAX_STACK_ALLOCATION: usize = 384;
#[cfg(target_os = "espidf")]
const MAX_STACK_ALLOCATION: usize = 32;

const NUL_ERR: io::Error =
    io::const_error!(io::ErrorKind::InvalidInput, "file name contained an unexpected NUL byte");

#[inline]
pub fn run_path_with_cstr<T>(path: &Path, f: &dyn Fn(&CStr) -> io::Result<T>) -> io::Result<T> {
    run_with_cstr(path.as_os_str().as_encoded_bytes(), f)
}

#[inline]
pub fn run_with_cstr<T>(bytes: &[u8], f: &dyn Fn(&CStr) -> io::Result<T>) -> io::Result<T> {
    // Dispatch and dyn erase the closure type to prevent mono bloat.
    // See https://github.com/rust-lang/rust/pull/121101.
    if bytes.len() >= MAX_STACK_ALLOCATION {
        run_with_cstr_allocating(bytes, f)
    } else {
        unsafe { run_with_cstr_stack(bytes, f) }
    }
}

/// # Safety
///
/// `bytes` must have a length less than `MAX_STACK_ALLOCATION`.
unsafe fn run_with_cstr_stack<T>(
    bytes: &[u8],
    f: &dyn Fn(&CStr) -> io::Result<T>,
) -> io::Result<T> {
    let mut buf = MaybeUninit::<[u8; MAX_STACK_ALLOCATION]>::uninit();
    let buf_ptr = buf.as_mut_ptr() as *mut u8;

    unsafe {
        ptr::copy_nonoverlapping(bytes.as_ptr(), buf_ptr, bytes.len());
        buf_ptr.add(bytes.len()).write(0);
    }

    match CStr::from_bytes_with_nul(unsafe { slice::from_raw_parts(buf_ptr, bytes.len() + 1) }) {
        Ok(s) => f(s),
        Err(_) => Err(NUL_ERR),
    }
}

#[cold]
#[inline(never)]
fn run_with_cstr_allocating<T>(bytes: &[u8], f: &dyn Fn(&CStr) -> io::Result<T>) -> io::Result<T> {
    match CString::new(bytes) {
        Ok(s) => f(&s),
        Err(_) => Err(NUL_ERR),
    }
}

    fn spec_new_impl_bytes(bytes: &[u8]) -> Result<CString, NulError> {
        // We cannot have such large slice that we would overflow here
        // but using `checked_add` allows LLVM to assume that capacity never overflows
        // and generate twice shorter code.
        // `saturating_add` doesn't help for some reason.
        let capacity = bytes.len().checked_add(1).unwrap();

        // Allocate before validation to avoid duplication of allocation code.
        // We still need to allocate and copy memory even if we get an error.
        let mut buffer = Vec::with_capacity(capacity);
        buffer.extend(bytes);

        // Check memory of self instead of new buffer.
        // This allows better optimizations if lto enabled.
        match memchr::memchr(0, bytes) {
            Some(i) => Err(NulError(i, buffer)),
            None => Ok(unsafe { CString::_from_vec_unchecked(buffer) }),
        }
    }

    impl SpecNewImpl for &'_ [u8] {
        fn spec_new_impl(self) -> Result<CString, NulError> {
            spec_new_impl_bytes(self)
        }
    }

    impl SpecNewImpl for &'_ str {
        fn spec_new_impl(self) -> Result<CString, NulError> {
            spec_new_impl_bytes(self.as_bytes())
        }
    }

    impl SpecNewImpl for &'_ mut [u8] {
        fn spec_new_impl(self) -> Result<CString, NulError> {
            spec_new_impl_bytes(self)
        }
    }

    t.spec_new_impl()
}

unsafe fn _from_vec_unchecked(mut v: Vec<u8>) -> Self {
    v.reserve_exact(1);
    v.push(0);
    Self { inner: v.into_boxed_slice() }
}

